// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 健康检查（含 DB 连通性）
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// 文章审阅列表（可按状态、平台、选题过滤）
	// (GET /v1/articles)
	ListArticles(w http.ResponseWriter, r *http.Request, params ListArticlesParams)
	// 文章详情（原稿、版本链、最新评分和发布记录）
	// (GET /v1/articles/{articleId})
	GetArticle(w http.ResponseWriter, r *http.Request, articleId ArticleId)
	// 人工终审通过（pending_review → approved）
	// (POST /v1/articles/{articleId}/approve)
	ApproveArticle(w http.ResponseWriter, r *http.Request, articleId ArticleId)
	// 文章评分历史（倒序）
	// (GET /v1/articles/{articleId}/evaluations)
	ListArticleEvaluations(w http.ResponseWriter, r *http.Request, articleId ArticleId)
	// 登记一次人工发布；首次登记同时执行 approved → published
	// (POST /v1/articles/{articleId}/publications)
	CreatePublication(w http.ResponseWriter, r *http.Request, articleId ArticleId)
	// 人工终审拒绝（pending_review → rejected）
	// (POST /v1/articles/{articleId}/reject)
	RejectArticle(w http.ResponseWriter, r *http.Request, articleId ArticleId)
	// 手动投喂 URL（刷到好东西时的一键入口，SPEC-003 §2.2）
	// (POST /v1/ingest/url)
	IngestUrl(w http.ResponseWriter, r *http.Request)
	// Reflector 经验库
	// (GET /v1/insights)
	ListInsights(w http.ResponseWriter, r *http.Request, params ListInsightsParams)
	// 人工启用或退役一条经验
	// (PATCH /v1/insights/{insightId})
	UpdateInsight(w http.ResponseWriter, r *http.Request, insightId InsightId)
	// 原子批量导入 Client 已解析和预检查的 CSV 指标
	// (POST /v1/metrics/import)
	ImportMetricSnapshots(w http.ResponseWriter, r *http.Request)
	// 平台内表现分分布、快照覆盖和近期 high/low case
	// (GET /v1/performance/dashboard)
	GetPerformanceDashboard(w http.ResponseWriter, r *http.Request, params GetPerformanceDashboardParams)
	// 最近的固定节奏调度运行
	// (GET /v1/pipeline/runs)
	ListPipelineRuns(w http.ResponseWriter, r *http.Request, params ListPipelineRunsParams)
	// 固定节奏内容流水线总览
	// (GET /v1/pipeline/summary)
	GetPipelineSummary(w http.ResponseWriter, r *http.Request)
	// 发布记录、标准快照完成度与待录提醒
	// (GET /v1/publications)
	ListPublications(w http.ResponseWriter, r *http.Request, params ListPublicationsParams)
	// 一次发布的全部累计指标快照
	// (GET /v1/publications/{publicationId}/metrics)
	ListMetricSnapshots(w http.ResponseWriter, r *http.Request, publicationId PublicationId)
	// 录入一条 24h/72h/7d 或自定义累计指标快照
	// (POST /v1/publications/{publicationId}/metrics)
	CreateMetricSnapshot(w http.ResponseWriter, r *http.Request, publicationId PublicationId)
	// 手动触发指定周期或最近七天的反思
	// (POST /v1/reflections/run)
	TriggerMemoryReflect(w http.ResponseWriter, r *http.Request)
	// 周度归因与评分校准报告
	// (GET /v1/reports/weekly)
	ListWeeklyReports(w http.ResponseWriter, r *http.Request, params ListWeeklyReportsParams)
	// 立即跑一次选题聚合（不等调度；忽略 minNewItems）
	// (POST /v1/scout/run)
	TriggerTopicScout(w http.ResponseWriter, r *http.Request)
	// 读调度设置
	// (GET /v1/settings/schedules)
	GetSchedulerSettings(w http.ResponseWriter, r *http.Request)
	// 改调度设置（≤ 1 个 tick 生效；重启不被环境变量覆盖）
	// (PATCH /v1/settings/schedules)
	UpdateSchedulerSettings(w http.ResponseWriter, r *http.Request)
	// 信源列表（含采集健康状态）
	// (GET /v1/sources)
	ListSources(w http.ResponseWriter, r *http.Request, params ListSourcesParams)
	// 新增信源
	// (POST /v1/sources)
	CreateSource(w http.ResponseWriter, r *http.Request)
	// 删除信源（已采集的 raw_items 保留，仅解除订阅）
	// (DELETE /v1/sources/{sourceId})
	DeleteSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// 信源详情
	// (GET /v1/sources/{sourceId})
	GetSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// 修改信源（含启停与单独采集频率覆盖）
	// (PATCH /v1/sources/{sourceId})
	UpdateSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// 立即采集该信源（不等调度）
	// (POST /v1/sources/{sourceId}/fetch)
	TriggerSourceFetch(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// 选题列表（按状态过滤，latestScore 倒序）
	// (GET /v1/topics)
	ListTopics(w http.ResponseWriter, r *http.Request, params ListTopicsParams)
	// 手动创建选题（M0 验收：空管道插入一条手动 topic）
	// (POST /v1/topics)
	CreateManualTopic(w http.ResponseWriter, r *http.Request)
	// 选题详情
	// (GET /v1/topics/{topicId})
	GetTopic(w http.ResponseWriter, r *http.Request, topicId TopicId)
	// 人工确认选题（scored → approved）
	// (POST /v1/topics/{topicId}/approve)
	ApproveTopic(w http.ResponseWriter, r *http.Request, topicId TopicId)
	// 选题的评分历史（维度分 + 理由 + rubric/权重版本，倒序）
	// (GET /v1/topics/{topicId}/evaluations)
	ListTopicEvaluations(w http.ResponseWriter, r *http.Request, topicId TopicId)
	// 人工否决选题（candidate/scored → rejected）
	// (POST /v1/topics/{topicId}/reject)
	RejectTopic(w http.ResponseWriter, r *http.Request, topicId TopicId)
	// 查询工作流运行记录
	// (GET /v1/workflow/runs)
	ListWorkflowRuns(w http.ResponseWriter, r *http.Request, params ListWorkflowRunsParams)
	// 手动触发一次内容流水线
	// (POST /v1/workflow/runs)
	CreateWorkflowRun(w http.ResponseWriter, r *http.Request)
	// 查询一次工作流运行
	// (GET /v1/workflow/runs/{runId})
	GetWorkflowRun(w http.ResponseWriter, r *http.Request, runId openapi_types.UUID)
	// 查询工作流产物
	// (GET /v1/workflow/runs/{runId}/artifacts)
	ListWorkflowArtifacts(w http.ResponseWriter, r *http.Request, runId openapi_types.UUID)
	// 比较父运行与 replay 运行
	// (POST /v1/workflow/runs/{runId}/compare)
	CompareWorkflowRuns(w http.ResponseWriter, r *http.Request, runId openapi_types.UUID)
	// 查询工作流事件
	// (GET /v1/workflow/runs/{runId}/events)
	ListWorkflowEvents(w http.ResponseWriter, r *http.Request, runId openapi_types.UUID, params ListWorkflowEventsParams)
	// 查询节点逐条判定
	// (GET /v1/workflow/runs/{runId}/nodes/{nodeKey}/decisions)
	ListWorkflowNodeDecisions(w http.ResponseWriter, r *http.Request, runId openapi_types.UUID, nodeKey WorkflowNodeKey, params ListWorkflowNodeDecisionsParams)
	// 从指定节点创建不可变 replay 子运行
	// (POST /v1/workflow/runs/{runId}/replay)
	ReplayWorkflowRun(w http.ResponseWriter, r *http.Request, runId openapi_types.UUID)
	// 查询工作流节点输入输出快照
	// (GET /v1/workflow/runs/{runId}/snapshots/{snapshotId})
	GetWorkflowSnapshot(w http.ResponseWriter, r *http.Request, runId openapi_types.UUID, snapshotId openapi_types.UUID)
	// 订阅工作流事件
	// (GET /v1/workflow/runs/{runId}/stream)
	StreamWorkflowRun(w http.ResponseWriter, r *http.Request, runId openapi_types.UUID)
}

